    for title, desc in req_items:
        add_p(f"{title}: {desc}")

    # 2. КОНТЕНТ-АНАЛИЗ
    add_h1("2. Контент-анализ предметной области")
    add_p("Для выявления объективных потребностей целевой аудитории, типичных проблемных ситуаций и функциональных ожиданий от веб-сервиса бронирования развлекательного клуба был проведен контент-анализ открытых источников. В качестве эмпирической базы исследованы отзывы реальных посетителей боулинг- и бильярдных клубов на геоинформационных порталах (Яндекс Карты, 2ГИС, Отзовик, Zoon), статьи в отраслевых изданиях сферы гостеприимства и спортивные регламенты.")
    
    add_p("Кодировочная схема исследования включает пять ключевых категорий анализа:", bold_prefix="Методика и кодировочная схема: ")
    add_p("1. Категория «Бронирование и овербукинг» (код БР-ОБ) — индикаторы: потеря брони администратором, двойное бронирование дорожки/стола, занятость по приходу, отсутствие онлайн-расписания.")
    add_p("2. Категория «Тарификация и стык тарифов» (код ТАР-СТ) — индикаторы: споры из-за перерасчета цены на границе дня и вечера, неожиданная смена почасовой ставки, непрозрачные счета.")
    add_p("3. Категория «Вместимость дорожки и перегруз» (код ВМЕСТ) — индикаторы: теснота при игре компанией свыше 6 человек, долгое ожидание очереди броска, требование персонала доплатить за вторую дорожку по факту приезда.")
    add_p("4. Категория «Обслуживание бара и предзаказ» (код БАР-ПР) — индикаторы: длительное ожидание напитков и закусок, остывшая еда, отсутствие возможности заказать кухню к началу игры.")
    add_p("5. Категория «Программа лояльности и скидки» (код ЛОЯЛ) — индикаторы: забытая физическая карта, отказ в скидке без предъявления пластика, ручной перерасчет администратором.")
    add_p("В качестве единицы счета принималось единичное смысловое упоминание соответствующей проблемы или требования в анализируемом источнике.")

    add_h2("Таблица 1 — Результаты контент-анализа предметной области")
    
